# available on the platforms this tool runs on; keep the flags readable.
_O_NOFOLLOW = getattr(os, "O_NOFOLLOW", 0)
_O_DIRECTORY = getattr(os, "O_DIRECTORY", 0)


def _hash_regular_file_at(
    directory_fd: int, name: str, path: Path
) -> tuple[str, int, int]:
    """Read one directory-relative file in full, pinned through the open.

    The name is inspected with ``fstatat`` relative to the pinned
    directory descriptor and opened with ``openat`` plus
    ``O_NOFOLLOW``; the opened descriptor is fstat()ed and proved to be
    the exact regular inode the inspection named.  A symlink swapped in
    after the inspection cannot redirect the read; any failure raises
    with the path and reason.  Returns ``(digest, device, inode)``.
    """
    try:
        before = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
    except OSError as error:
        raise ExportError(f"cannot inspect entry {path}: {error}") from error
    if not stat.S_ISREG(before.st_mode):
        raise ExportError(f"cannot read source file {path}: not a regular file")
    try:
        descriptor = os.open(
            name, os.O_RDONLY | _O_NOFOLLOW, dir_fd=directory_fd
        )
    except OSError as error:
        if error.errno == errno.ELOOP:
            raise ExportError(
                f"cannot read source file {path}: path is now a symlink"
            ) from error
        raise ExportError(f"cannot read source file {path}: {error}") from error
    try:
        opened = os.fstat(descriptor)
        if not stat.S_ISREG(opened.st_mode) or (
            opened.st_dev,
            opened.st_ino,
        ) != (before.st_dev, before.st_ino):
            os.close(descriptor)
            raise ExportError(
                f"cannot read source file {path}: file changed while it was "
                f"being opened"
            )
        hasher = hashlib.sha256()
        with os.fdopen(descriptor, "rb") as stream:
            while True:
                chunk = stream.read(_CHUNK_SIZE)
                if not chunk:
                    break
                hasher.update(chunk)
    except OSError as error:
        raise ExportError(f"cannot read source file {path}: {error}") from error
    return hasher.hexdigest(), opened.st_dev, opened.st_ino

